// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<aside class=\"msg alert\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"1\" class=\"code-line\">This article was drafted by generative AI from <a href=\"https://www.youtube.com/watch?v=sGSKSh5yNIE\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.youtube.com/watch?v=sGSKSh5yNIE</a> as source material, then reviewed and edited by the author.</p>\n</div></aside>\n<aside class=\"msg message\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"5\" class=\"code-line\">These features are experimental. Consider carefully before using them in production.</p>\n</div></aside>\n<p data-line=\"8\" class=\"code-line\">Angular 19.2 is out! The highlights are experimental <strong>HTTP resource</strong> and <strong>response streaming</strong>. Signal-based development keeps getting more convenient.</p>\n<h2 id=\"http-resource-makes-async-handling-simpler\" data-line=\"11\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#http-resource-makes-async-handling-simpler\" aria-hidden=\"true\"></a> HTTP resource makes async handling simpler</h2>\n<p data-line=\"13\" class=\"code-line\">The <strong>HTTP resource</strong> re-released experimentally in Angular v19 is very handy. Loading, success, and error states for async work can be written much more simply with Signals.</p>\n<p data-line=\"15\" class=\"code-line\">Consider a component that shows a user profile. The traditional approach:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"17\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-user-profile'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"loading\"&gt;Loading...&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"error\"&gt;{{ error }}&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"user\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;h2&gt;{{ user.name }}&lt;/h2&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;p&gt;{{ user.email }}&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserProfileComponent</span><span style=\"color:#F97583\"> implements</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  user</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> User</span><span style=\"color:#F97583\"> |</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  loading</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> false</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  error</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#F97583\"> |</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.loading </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> true</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#9ECBFF\">'/api/user'</span><span style=\"color:#E1E4E8\">).</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      finalize</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.loading </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> false</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ).</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      next</span><span style=\"color:#E1E4E8\">: (</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.user </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> user,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      error</span><span style=\"color:#E1E4E8\">: (</span><span style=\"color:#FFAB70\">err</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.error </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> err.message</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"49\" class=\"code-line\">With HTTP resource:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-user-profile'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"userResource.isLoading\"&gt;Loading...&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"userResource.error\"&gt;{{ userResource.error }}&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"userResource.hasValue\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;h2&gt;{{ userResource.value.name }}&lt;/h2&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;p&gt;{{ userResource.value.email }}&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserProfileComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/api/user'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"68\" class=\"code-line\">Much simpler! Properties like <code>isLoading</code> and <code>hasValue</code> are provided as Signals, so template state management is easy.</p>\n<h2 id=\"response-streaming-for-smarter-real-time-data\" data-line=\"70\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#response-streaming-for-smarter-real-time-data\" aria-hidden=\"true\"></a> Response streaming for smarter real-time data</h2>\n<p data-line=\"72\" class=\"code-line\">The other experimental feature, <strong>response streaming</strong>, is promising too. It should shine in chat apps and anything that updates data in real time.</p>\n<p data-line=\"74\" class=\"code-line\">For example, displaying messages in a chat app:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"76\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-chat'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div class=\"messages\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div *ngFor=\"let message of messagesResource.value\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;div class=\"message\"&gt;{{ message.text }}&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div *ngIf=\"messagesResource.isLoading\"&gt;Loading messages...&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ChatComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  messagesResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> rxResource</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    inject</span><span style=\"color:#E1E4E8\">(ChatService).</span><span style=\"color:#B392F0\">getMessageStream</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"95\" class=\"code-line\">I no longer need to subscribe to Observables and manage state manually. I can write more declaratively with Signals.</p>\n<h2 id=\"template-literal-expressions-supported-too\" data-line=\"97\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#template-literal-expressions-supported-too\" aria-hidden=\"true\"></a> Template literal expressions supported too</h2>\n<p data-line=\"99\" class=\"code-line\">Angular 19.2 also improves the in-template developer experience. Support for <strong>untagged template literal expressions</strong> makes expressions in templates more intuitive.</p>\n<p data-line=\"101\" class=\"code-line\">Traditional style:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"102\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;{{ (user$ | async)?.name }}'s balance: {{ (balance$ | async) | currency }}&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"106\" class=\"code-line\">New style:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"107\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;${(user$ | async)?.name}'s balance: ${(balance$ | async) | currency}&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"111\" class=\"code-line\">Personally, this is still experimental, so I want to wait before using it in production. Still, it feels like it could be very useful down the road.</p>\n<h2 id=\"summary\" data-line=\"113\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"115\" class=\"code-line\">The new features in Angular 19.2—especially HTTP resource—feel quite practical, and I hope they stabilize soon. Signal-based development keeps evolving.</p>\n<p data-line=\"117\" class=\"code-line\">The Angular team is actively seeking feedback on these features. Checking GitHub RFCs and sharing opinions is worthwhile.</p>\n<p data-line=\"119\" class=\"code-line\">See you next time!</p>\n","headings":[{"id":"http-resource-makes-async-handling-simpler","text":"HTTP resource makes async handling simpler","level":2},{"id":"response-streaming-for-smarter-real-time-data","text":"Response streaming for smarter real-time data","level":2},{"id":"template-literal-expressions-supported-too","text":"Template literal expressions supported too","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
